                this.index = 0;
            }
            while (this.index < this.moves) {
                int mv = this.mvs[this.index];
                ++this.index;
                if (mv == this.mvHash || mv == this.mvKiller1 || mv == this.mvKiller2) continue;
                return mv;
            }
            return 0;
        }
    }
