        this.x = x;
        this.y = y;
        this.type = type;
    }

    public static CompoundTag toTag(Point point) {
        CompoundTag tag = new CompoundTag();
        tag.m_128405_("x", point.x);
        tag.m_128405_("y", point.y);
        tag.m_128405_("type", point.type);
        return tag;
    }

    public static Point fromTag(CompoundTag tag) {
        int x = tag.m_128451_("x");
        int y = tag.m_128451_("y");
        int type = tag.m_128451_("type");
        return new Point(x, y, type);
    }

    public boolean equals(Object other) {
        if (other == null) {
            return false;
        }
        if (this == other) {
            return true;
        }
        if (other instanceof Point) {
            Point otherPoint = (Point)other;
            return otherPoint.x == this.x && otherPoint.y == this.y && otherPoint.type == this.type;
        }
        return false;
    }

    public String toString() {
        return (this.type == 1 ? "Black" : "White") + "[" + this.x + "," + this.y + "]";
    }
}

